export function coerceToSchema(value: unknown, schema: JsonSchema): Coercion;

// fixes, in order, each recorded in `applied`:
//   "unfence"      ```json … ```          → inner text
//   "extract"      prose + {…} + prose    → first balanced JSON value
//   "unwrap"       {result:{value:X}}     → X, when the schema does not describe that shape
//   "scalar"       "42" / "true"          → 42 / true, when type says number/integer/boolean
//   "wrap-array"   X                      → [X], when type says array and items accepts X
