// stdlib/src/best-of.ts
export interface BestOfPatchOptions<S extends AnySchema> {
  key: string;
  prompt: string;
  schema: S;
  write: WriteScope;
  /** One candidate per entry; vary model/effort/provider for real diversity. */
  candidates: ReadonlyArray<Routing>;
  /** Required gate: a candidate that fails is dropped before any judging happens. */
  verify?: CheckOptions & { name: string };
  /** Judges among survivors; defaults to 1. Order shuffled via ctx.random(). */
  judges?: number;
}
export interface BestOfPatchResult<T> {
  winner: DetailedAgentResult<T>;
  considered: number; verified: number; discarded: string[];
}
export async function bestOfPatch<S extends AnySchema>(
  ctx: Ctx, opts: BestOfPatchOptions<S>,
): Promise<BestOfPatchResult<InferOut<S>>>;

